        skip_files_hint: "Voer de exacte namen van de uitvoerbestanden in om over te slaan, gescheiden door komma's. Voorbeeld: output1.csv,output2.csv",
        err_title_save_scenario: "Er is een fout opgetreden bij het opslaan van uw scenario",
        msg_required_for_check: "Sommige kleinere uitvoerbestanden worden gebruikt in SWAT+ Check en het deselecteren ervan is uitgeschakeld.",
